(window.TNQ=window.TNQ||[]).push({"terms":{"전이":{"d":"과거 중요한 인물에 대한 감정을 현재 상대에게 옮겨 느끼는 현상입니다.","r":[]},"관찰학습":{"d":"다른 사람의 행동과 결과를 보고 그 행동을 배우는 학습입니다.","r":[]},"치료적 동맹":{"d":"클라이언트와 사회복지사가 목표와 과제에 합의하며 맺는 협력적 신뢰관계입니다.","r":[]},"자기노출":{"d":"사회복지사가 자신의 경험이나 감정 같은 개인 정보를 의도적으로 드러내는 것입니다.","r":[]},"순환적 인과성":{"d":"원인과 결과가 일직선이 아니라 서로 영향을 주고받으며 이어지는 관계입니다.","r":["가족 항상성"]},"가족 항상성":{"d":"가족이 변화에 맞서 기존의 균형과 안정을 유지하려는 경향입니다.","r":["순환적 인과성"]},"하위체계":{"d":"가족 안에서 부부나 형제처럼 역할로 묶인 더 작은 단위의 체계입니다.","r":[]},"자아분화":{"d":"감정과 사고를 구분하고 가족에게서 정서적으로 독립하는 정도로 보웬 이론의 핵심입니다.","r":[]},"긍정적 의미부여":{"d":"가족의 문제 행동에 긍정적인 의도가 있다고 새롭게 해석해 주는 밀란 모델의 기법입니다.","r":[]},"정화효과":{"d":"집단 안에서 억눌린 감정을 표현해 마음이 후련해지는 치료적 경험입니다.","r":[]},"집단응집력":{"d":"성원들이 집단에 끌려 소속감을 느끼고 함께 머물려는 힘입니다.","r":[]},"개방형 집단":{"d":"집단 진행 중에도 새 성원이 들어올 수 있는 집단입니다.","r":[]},"기초선":{"d":"개입 전에 측정한 문제 행동의 수준으로, 개입 효과를 가늠하는 비교 기준입니다.","r":["반복측정"]},"반복측정":{"d":"같은 변수를 여러 시점에 되풀이해 재어 변화 경향을 파악하는 것입니다.","r":["기초선"]}},"notes":{"가장 기본적인 유형이며 ABC설계보다 개입의 효과를 더 명확하게 보여준다":"개입을 거두었다가 다시 시작해도 같은 변화가 나타나면 효과가 개입 때문임이 더 분명해집니다.","가족구성원의 불안 감소 및 미분화된 원가족과의 관계에서 자아분화를 증진 시킨다":"다세대 가족치료는 원가족과 정서적으로 엉킨 상태를 풀어 불안을 줄이고 자아분화를 높입니다.","가족 규칙은 가족 항상성에 영향을 준다":"규칙이 행동의 범위를 정해 주기 때문에 가족이 균형을 유지하는 방식도 달라집니다.","가족규칙을 합리적으로 바꾸고, 자기 인생에 대한 선택권을 스스로 갖도록 한다":"경직된 가족규칙을 융통성 있게 고쳐 구성원이 자기 삶을 스스로 선택하게 합니다.","가족성원의 행동은 순환적 인과성의 특성을 갖는다":"한 사람의 행동이 다른 사람의 반응을 낳고 그것이 다시 처음 행동에 영향을 주는 고리를 이룹니다.","가족은 하위체계이면서 상위체계이다":"가족은 사회라는 더 큰 체계의 일부이면서 부부와 형제 같은 작은 체계를 품고 있습니다.","가족응집력을 향상시키고 치료에 대한 저항을 줄이기 위해 긍정적 의미부여 기법을 사용한다":"문제 행동을 가족을 위한 노력으로 다시 해석하면 가족이 덜 방어하고 더 가까워집니다.","가족이 문제 중심에서 벗어나 해결방안을 모색하고 실행하도록 돕는다":"문제를 분석하는 데 머물지 않고 가족이 바라는 해결 쪽으로 눈을 돌려 실행하게 합니다.","가족 형태가 다양해지는 경향이 있다":"한부모, 재혼, 무자녀 가족처럼 전통적인 가족 외의 형태가 늘어나고 있습니다.","개방형 집단에 비해 집단 규범이 안정적이다":"폐쇄형 집단은 성원이 바뀌지 않아 규범이 흔들리지 않고 유지됩니다.","개인과 사회에 관한 주관적 인식의 차이를 보여주는 사고체계":"관점은 개인과 사회를 어떻게 바라보는가에 따라 사람마다 달라지는 생각의 틀입니다.","개인뿐 아니라 가족, 집단, 기관도 가능하다":"단일사례설계의 사례는 한 사람에 한정되지 않고 가족이나 기관 같은 하나의 단위도 됩니다.","개인의 가치체계와 경험으로부터 만들어진다":"실천 지식은 학문 이론이 아니라 실천가가 가진 가치관과 현장 경험에서 나옵니다.","개인의 주관적 경험의 독특성을 중시한다":"인지치료는 같은 사건도 사람마다 달리 받아들이므로 개인의 주관적 경험을 존중합니다.","개인정보가 담긴 사례기록을 방치하는 것은 위법 행위이다":"클라이언트의 개인정보가 든 기록을 아무렇게나 두면 법을 어기는 행위가 됩니다.","개입과정에서 개입의 강도나 방식을 바꿀 수 있다":"재사정 결과에 따라 개입의 세기와 방법을 조정하는 일입니다.","개입의 효과성을 파악하기 위해 반복측정을 한다":"여러 시점에 같은 변수를 재야 변화의 흐름을 알 수 있어 반복측정이 필수입니다.","건설적이고 생산적인 집단변화를 위해 개입단계에서 사용한다":"집단이 좋은 방향으로 변하도록 개입단계에서 적절히 자신을 드러냅니다.","건설적인 직면을 통해 참여동기를 강화한다":"비자발적으로 온 성원에게 비난 없이 현실을 마주하게 하면 참여하려는 마음이 커집니다.","경험적 확신을 갖도록 전이와 저항에 대한 분석과 해석을 반복적으로 진행하는 것":"깨달은 내용이 몸에 배도록 전이와 저항을 여러 번 짚어 가며 해석해 주는 과정입니다.","고정관념이나 편견이 많은 성원들은 집단문화 형성에 방해가 된다":"성원이 서로를 열린 마음으로 대하지 못하면 공통의 문화가 만들어지기 어렵습니다.","과제 활용과 교육적인 접근으로 자기 치료가 가능하도록 한다":"숙제와 교육을 통해 클라이언트가 상담이 끝나도 스스로 문제를 다루게 합니다.","관찰학습을 통해 클라이언트가 취할 행동을 학습하게 한다":"모델링은 다른 사람이 행동하는 모습을 보여 주어 클라이언트가 따라 배우게 합니다.","교육적 접근을 통해 재발방지역량을 강화하는데 초점을 맞춘다":"문제가 다시 생기는 것을 막을 대처 방법을 가르쳐 클라이언트의 힘을 키웁니다.","구체적이고 관찰 가능한 문제에 초점을 두고 과거보다 현재에 초점을 둔다":"위기개입은 눈에 보이는 문제를 지금 이 순간 해결하는 데 집중합니다.","기초선과 개입단계의 구분은 분명해야 한다":"그래프에서 개입 전후를 나누는 선이 분명해야 두 구간의 차이를 비교할 수 있습니다.","기초선 자료수집은 개입 이전이나 이후에도 가능하다":"기초선은 개입 전에 모으는 것이 원칙이지만 이전 기록이 없으면 개입 이후에 모으는 방법도 있다는 내용입니다.","다른 개입모델에 비해 적극적이고 직접적인 역할을 수행한다":"위기 상황은 급하게 안정시켜야 하므로 사회복지사가 먼저 나서서 적극적으로 개입합니다.","당사자들이 세운 규칙에 의해 운영되며 시간 제한적일 필요는 없다":"자조집단은 전문가가 정한 틀이 아니라 성원이 만든 규칙으로 굴러가고 기간이 정해지지 않아도 됩니다.","대인관계에 관한 사회기술을 습득한다":"집단 안에서 사람들과 주고받는 경험을 하며 관계를 맺는 방법을 배웁니다.","모든 사람은 강점과 자원, 능력을 가지고 있다고 가정한다":"문제가 있어도 사람에게는 활용할 수 있는 힘이 있다는 전제에서 출발합니다.","목표달성을 위한 구체적인 과제들에 대해 작업한다":"막연한 목표를 그대로 두지 않고 실행 가능한 구체적 과제로 쪼개 하나씩 해 나갑니다.","무의식적인 미해결 과제를 분석하여 통찰력을 갖게 한다":"꿈을 해석해 마음속에 풀리지 않고 남은 문제를 알아차리게 하는 기법입니다.","문제가 개선될 수 있다는 희망을 갖게 한다":"먼저 나아진 성원을 보면서 자신도 좋아질 수 있다는 기대를 얻는 치료적 요인입니다.","문제의 원인과 발전과정에 관심을 두기보다 문제해결 방안을 모색하는 것이 더 효과적이라고 본다":"해결중심모델은 문제가 왜 생겼는지 캐기보다 해결책을 찾는 데 시간을 씁니다.","미분화된 가족체계의 관계패턴이 세대에 걸쳐 반복되는 현상":"자아분화가 낮은 가족의 관계 방식이 부모에서 자녀로 대를 이어 되풀이됩니다.","미성숙한 부모가 불안을 낮추기 위해 가장 취약한 자녀에게 자신의 불안을 투사하는 현상":"부모가 자기 불안을 덜려고 가장 약한 자녀에게 문제를 옮겨 씌우는 일입니다.","민주시민의 역량 개발에 초점을 둔다":"사회적 목표모델은 집단 활동으로 성원이 사회에 참여하고 책임지는 시민의 능력을 키우는 데 둡니다.","부모와 해결되지 못한 정서적 문제가 현재의 가족에 부정적 영향을 미친다":"원가족의 부모와 풀지 못한 감정이 지금 꾸린 가족관계에까지 나쁜 영향을 줍니다.","사건에 대한 클라이언트의 인식, 사고, 감정, 외부 환경의 영향을 성찰하게 한다":"사건을 어떻게 받아들이고 느꼈는지와 환경이 준 영향을 돌아보게 하는 기법입니다.","사회복지 가치와 윤리를 반영한다":"기술을 쓸 때도 클라이언트 존엄성과 같은 사회복지의 가치와 윤리를 지켜야 합니다.","사회복지사가 언어적 혹은 비언어적 행동을 통해 의도적으로 자신에 관한 정보를 누설하는 것을 의미한다":"자기노출은 말이나 행동으로 사회복지사가 목적을 갖고 자신에 관한 정보를 알리는 일입니다.","사회복지사가 클라이언트에게 필요한 조언이나 제안을 한다":"사회복지사가 조언과 제안으로 클라이언트의 행동에 직접 영향을 주는 개입입니다.","사회복지사보다 클라이언트가 제시하는 문제나 욕구를 고려하여 선정한다":"과제중심모델은 전문가가 정한 문제보다 클라이언트가 인식하는 문제를 우선해 선정합니다.","사회복지사의 직관에 영향을 받는다":"실천 지식은 사회복지사가 경험에서 얻은 감각, 곧 직관의 영향을 받습니다.","사회복지의 관점과 이론을 토대로 한다":"기술은 임의로 쓰지 않고 사회복지의 관점과 이론에 근거를 두고 선택됩니다.","성격, 행동, 감정의 주요 경향에 관한 자기이해를 돕는다":"자신에게 반복되는 성격과 행동과 감정의 흐름을 깨닫게 하여 자기 이해를 넓힙니다.","성원들의 가치가 혼합되면서 타 집단과 구분되는 특성이 만들어진다":"성원들이 가진 가치관이 섞여 그 집단만의 고유한 성격이 생깁니다.","세대구성이 단순화되면서 확대가족의 의미가 약화된다":"함께 사는 세대 수가 줄어들면서 여러 세대가 묶인 확대가족의 비중이 낮아집니다.","실천과정에 직접적으로 필요한 기술적 적용방법을 제시한 것":"모델은 이론을 실제 실천에서 어떻게 적용할지 구체적인 절차와 기법으로 정리한 것입니다.","양육, 보호, 교육, 부양 등에서 사회 이슈가 발생한다":"가족이 맡던 기능이 약해지면서 돌봄과 교육과 부양을 사회가 어떻게 나눌지가 문제로 떠오릅니다.","어떤 행동이 허용되는가를 결정하는 가족규칙":"가족규칙은 가족 안에서 되는 행동과 안 되는 행동을 정하는 암묵적 약속입니다.","역기능적 가족구조를 재구조화한다":"구조적 가족치료는 경계가 불분명하거나 위계가 어긋난 가족구조를 바로잡습니다.","역기능적 의사소통 유형을 일치형으로 바꾸도록 돕는다":"비난형이나 회유형처럼 한쪽에 치우친 소통을 자신과 상대와 상황을 모두 존중하는 일치형으로 바꿉니다.","역사와 사상의 흐름에 영향을 받는 추상적 개념 틀":"패러다임은 시대의 역사와 사상의 영향을 받아 형성되는 포괄적이고 추상적인 틀입니다.","욕구를 재확인하여 서비스 계획이나 개입전략을 수정하는 과정이다":"처음 세운 계획이 맞지 않을 수 있어 욕구를 다시 확인하고 개입 방향을 고칩니다.","위기사건 이후 상황과 관련된 자료를 보충한다":"위기가 일어난 뒤의 상황을 이해하려고 필요한 정보를 더 모으는 일입니다.","위로, 지지 등으로 서로 도움을 주고 받는다":"이타심은 성원이 서로를 위로하고 지지하며 도움을 주는 데서 자기 가치를 느끼는 요인입니다.","이해, 격려, 확신감을 표현하는 기법":"지지는 클라이언트가 불안할 때 이해와 격려로 안정을 느끼게 하는 간접적 개입 기법입니다.","인간의 비합리적인 신념이 행동과 정서 문제를 초래한다고 본다":"엘리스는 사건 자체보다 그것을 해석하는 비합리적 신념이 정서 문제를 일으킨다고 보았습니다.","일반적 과제에 비해 구체적이다":"조작적 과제는 누가 언제 무엇을 할지 분명한 실행 단위여서 일반 과제보다 구체적입니다.","자기 상황과 감정을 말로 표현하게 함으로써 감정전환을 도모하는 기법":"감정을 말로 꺼내 놓으면 쌓인 감정이 풀려 마음 상태가 달라지는 환기 효과가 생깁니다.","자아존중감을 높이는 것이 중요한 치료목표이다":"사티어 모델은 자신을 가치 있게 여기는 감정이 건강한 소통의 바탕이라고 보고 이를 목표로 삼습니다.","자아존중감 향상과 의사소통 방식의 변화를 통해 대처능력을 향상시킨다":"경험적 가족치료는 자신을 소중히 여기고 말하는 방식을 바꾸게 해 대처 능력을 키웁니다.","저출산 시대에는 무자녀 부부가 증가한다":"출산을 적게 하는 사회에서는 자녀 없이 지내는 부부도 늘어납니다.","정신내적인 개념인 동시에 대인관계적 개념이다":"자아분화는 감정과 사고를 구별하는 내면의 능력이자 타인과 정서적으로 거리를 두는 관계 능력입니다.","정확한 정보를 기록하고, 부정확한 것으로 확인되면 삭제나 수정할 수 있다":"사례기록은 사실에 맞아야 하므로 틀린 내용은 바로잡을 수 있습니다.","제한된 시간 내에 특정 문제에 초점을 두고 접근한다":"인지행동모델은 장기 탐색 대신 정해진 기간에 구체적인 문제를 겨냥해 개입합니다.","지나친 자기노출은 집단에 부정적 영향을 줄 수 있다":"초기에 사회복지사가 자신을 너무 드러내면 성원이 부담을 느끼고 신뢰를 잃을 수 있습니다.","집단 고유의 스타일이나 독특성을 만들어낸다":"집단문화는 그 집단이 일하고 소통하는 고유한 방식으로 나타납니다.","집단성원에 대한 주요 통제수단이기 때문에 규범설정이 중요하다":"집단 규범은 성원의 행동을 조절하는 기준이므로 집단 초기에 분명히 세워야 합니다.","집단응집력은 집단문화 형성에 영향을 미치는 요인이다":"성원이 집단에 소속감을 느낄수록 공통의 분위기와 규범이 더 쉽게 자리 잡습니다.","집단의 목표와 관련이 있어야 한다":"자기노출은 집단의 목표를 이루는 데 도움이 되는 내용에 한해 해야 합니다.","집단참여를 통해 정화효과를 경험하기도 한다":"집단에서 감정을 드러내고 공감받으면서 마음이 후련해지는 경험을 하기도 합니다.","클라이언트가 힘들어하는 행동에 대해 실생활에서 실행 전에 반복적으로 연습하는 것":"시연은 어려운 행동을 실제 상황에 닥치기 전에 미리 연습해 보는 기법입니다.","클라이언트 스스로 자신에 대해 독백하고 사고하는 과정이다":"마음속으로 자신에게 하는 말을 알아차리게 하여 그 생각의 내용과 영향을 분명히 하는 기법입니다.","클라이언트에게 실용적 정보를 제공하고 지지체계를 개발하도록 한다":"당장 쓸 수 있는 정보를 주고 기댈 수 있는 사람과 기관을 마련하게 돕습니다.","클라이언트와 사회복지사의 치료적 동맹관계가 중요하다":"인지행동모델은 두 사람이 한 팀으로 협력할 때 효과가 나므로 동맹을 중시합니다.","클라이언트의 과거에 관해 깊이 탐색하여 현재와 미래에 적응하도록 돕는데 관심을 둔다":"과거를 깊이 파고드는 접근으로, 해결중심모델이 아닌 정신역동 계열 접근을 가리킵니다.","클라이언트의 문제해결능력에 대한 인정과 격려로 불안을 감소시킨다":"할 수 있는 힘이 있다고 인정해 주면 클라이언트의 불안이 낮아집니다.","클라이언트의 사생활이나 비밀스러운 내용은 일반적인 용어로 바꾸어 기록한다":"민감한 내용은 구체적으로 적지 않고 포괄적인 표현으로 써서 비밀을 지킵니다.","클라이언트의 성격이나 기능에 영향을 미친 원가족에서의 초기 경험을 성찰하게 한다":"어린 시절 원가족에서의 경험이 지금의 성격과 기능에 준 영향을 되짚게 하는 방법입니다.","클라이언트의 일상생활에 활용할 수 있는 자원과 지지체계를 찾아낸다":"클라이언트가 평소 쓸 수 있는 도움 자원과 주변의 지지체계를 파악해 과제 수행에 씁니다.","클라이언트의 적극적 참여와 협조적 태도를 중시한다":"과제를 수행하고 변화를 시도하는 주체가 클라이언트라서 적극적 참여가 필요합니다.","클라이언트의 특성을 반영한다":"같은 기술이라도 클라이언트의 연령과 상황에 따라 적용 방식이 달라집니다.","탈이론적이고 비규범적이며 클라이언트의 견해를 존중한다":"두 모델은 정해진 이론이나 규범으로 클라이언트를 재단하지 않고 그의 관점을 받아들입니다.","특정 이론보다는 경험적 자료를 통해 개입의 기초를 마련한다":"과제중심모델은 특정 이론에 얽매이지 않고 연구로 확인된 자료를 개입의 바탕으로 삼습니다.","특정 행동 수준까지 끌어올리기 위해 작은 단위의 행동으로 나누어 과제를 주는 것":"행동조성은 큰 목표 행동에 닿도록 쉬운 단계부터 차례로 과제를 주어 도달시킵니다.","하나의 사례에 초점을 두므로 클라이언트의 변화를 명확히 파악할 수 있다":"한 사례를 반복 측정하기 때문에 개입 전후 변화가 뚜렷하게 보입니다.","하위체계의 경계가 희미한 경우에는 감정의 합일현상이 증가한다":"하위체계 사이의 경계가 흐리면 구성원이 서로의 감정에 휩쓸려 하나처럼 움직입니다.","한 가족성원의 개입노력은 가족 전체에 영향을 준다":"가족 한 사람이 변하면 그 영향이 체계 전체로 퍼져 다른 구성원도 달라집니다.","한 가족성원이 보이는 증상은 가족의 문제를 대신해서 호소하는 것으로 본다":"가족체계 관점은 환자로 지목된 구성원이 가족 전체의 문제를 드러내는 신호라고 봅니다.","한 사람의 문제는 가족성원 모두에게 영향을 미친다":"가족은 서로 연결된 체계여서 한 구성원의 어려움이 나머지에게도 퍼집니다.","현상을 설명하기 위한 가설이나 개념의 집합체":"이론은 어떤 현상이 왜 일어나는지 설명하려고 가설과 개념을 체계적으로 묶은 것입니다.","현장에서 유용하나 공인된 지식은 아니다":"현장에서 쓸모는 있어도 검증을 거쳐 학계가 인정한 지식은 아닙니다.","현재 위기와 관련된 과거 경험을 탐색한다":"과거에 비슷한 위기를 어떻게 넘겼는지 되짚으면 지금의 대처 방법을 찾는 데 도움이 됩니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
